"% model.m
function model()
    % --- Aircraft Parameters ---
    W = 280000.0;       % Weight (lbf)
    S = 2730.0;         % Wing Area (ft^2)
    h = 35000.0;        % Altitude (ft)
    V = 780.0;          % True Airspeed (ft/s)
    gamma_deg = 5.0;    % Climb angle (deg)
    phi_deg = 40.0;     % Bank angle (deg)

    % Aerodynamics
    CL0 = 0.18;
    CLa = 5.6;          % per rad
    CLde = 0.3;         % per rad
    CD0 = 0.019;
    k = 0.045;

    % Atmosphere
    rho0 = 0.0023769;   % slug/ft^3
    h_scale = 23800.0;  % ft
    rho = rho0 * exp(-h / h_scale);
    q = 0.5 * rho * V^2;

    % Thrust & Geometry
    iT_deg = 3.0;       % Thrust pitch angle vs body (deg)
    zT = 2.2;           % Thrust arm (ft)
    cbar = 19.5;        % Mean chord (ft)

    % Pitching Moment
    Cm0 = 0.025;
    Cma = -0.34;        % per rad
    Cmde = -0.9;        % per rad

    % --- Derived Constants (Radians) ---
    gamma = deg2rad(gamma_deg);
    phi = deg2rad(phi_deg);
    iT = deg2rad(iT_deg);

    % --- Optimization Setup ---
    % We use fminsearch (available in base MATLAB) to minimize the sum of squared residuals.
    % Variables to solve for: [alpha_deg, T_kips, de_deg]
    % Scaling helps the optimizer perform better.

    % Initial Guess:
    % Alpha approx 5 deg, Thrust approx 45 kips, Elevator approx -1 deg
    x0 = [5.0; 45.0; -1.0];

    % Options
    options = optimset('Display', 'off', 'TolX', 1e-8, 'TolFun', 1e-8, 'MaxIter', 1000, 'MaxFunEvals', 5000);

    % Objective Function
    objective = @(x) compute_residuals_squared(x, ...
        W, S, q, gamma, phi, iT, zT, cbar, ...
        CL0, CLa, CLde, CD0, k, ...
        Cm0, Cma, Cmde);

    % Solve
    x_sol = fminsearch(objective, x0, options);

    % --- Extract and Convert Results ---
    alpha_trim_deg = x_sol(1);
    thrust_lbf = x_sol(2) * 1000.0;
    delta_e_trim_deg = x_sol(3);

    % Load Factor
    n = cos(gamma) / cos(phi);

    % --- Output ---
    result.alpha_trim_deg = alpha_trim_deg;
    result.thrust_lbf = thrust_lbf;
    result.delta_e_trim_deg = delta_e_trim_deg;
    result.load_factor = n;

    % Write to JSON
    fid = fopen('result.json', 'w');
    fprintf(fid, '%s', jsonencode(result));
    fclose(fid);
end

function E = compute_residuals_squared(x, ...
    W, S, q, gamma, phi, iT, zT, cbar, ...
    CL0, CLa, CLde, CD0, k, ...
    Cm0, Cma, Cmde)

    % Unpack and un-scale variables
    % x(1) = alpha (deg)
    % x(2) = T (kips)
    % x(3) = de (deg)

    alpha = deg2rad(x(1));
    T = x(2) * 1000.0;
    de = deg2rad(x(3));

    % Aerodynamic Coefficients
    CL = CL0 + CLa * alpha + CLde * de;
    CD = CD0 + k * CL^2;
    Cm = Cm0 + Cma * alpha + Cmde * de;

    % Equilibrium Equations
    % 1. Vertical force balance (perpendicular to flight path in vertical plane)
    % q*S*CL*cos(phi) + T*sin(alpha + iT) - W*cos(gamma) = 0
    F1 = q * S * CL * cos(phi) + T * sin(alpha + iT) - W * cos(gamma);

    % 2. Along flight path force balance
    % T*cos(alpha + iT) - q*S*CD - W*sin(gamma) = 0
    F2 = T * cos(alpha + iT) - q * S * CD - W * sin(gamma);

    % 3. Pitching moment balance about CG
    % q*S*cbar*(Cm) + T*sin(iT)*z_T = 0
    F3 = q * S * cbar * Cm + T * sin(iT) * zT;

    % Sum of squared errors
    E = F1^2 + F2^2 + F3^2;
end"
